#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Takes ownership and frees the report. Only this comment says so. */
static void archive(char *report) {
    printf("archived %s\n", report);
    free(report);
}

int main(void) {
    char *report = strdup("q3-summary");
    archive(report);
    free(report);                 /* ASan: attempting double-free */
    return 0;
}
